import { Button } from "./button";
import { Thread, type ThreadComment } from "./thread";
import type { InlineComment } from "./editor/comment-anchors";

type InlineCommentLayerProps = {
    label: string;
    comments: readonly InlineComment[];
    onCommentsChange: (comments: InlineComment[]) => void;
    onReply?: (threadId: string, parentId: string | null, content: string) =>
        void | Promise<void>;
    onSelect?: (comment: InlineComment) => void;
    onReattach?: (id: string) => void;
    disabled?: boolean;
};

function InlineCommentLayer({
    label, comments, onCommentsChange, onReply, onSelect, onReattach,
    disabled,
}: InlineCommentLayerProps) {
    return <aside aria-label={label} data-slot="inline-comment-layer"
        className="grid content-start gap-3">
        {comments.length === 0 &&
            <p className="text-sm text-muted">아직 댓글이 없습니다.</p>}
        {comments.map((item) => <section key={item.id}
            data-inline-thread-id={item.id} tabIndex={-1}
            className="grid gap-2 rounded-md border border-border p-3">
            <button type="button" disabled={disabled}
                onClick={() => onSelect?.(item)}
                className="text-left text-sm text-muted">
                {item.quote}
            </button>
            <p className="m-0 text-xs text-muted">
                {item.anchor === "orphaned" ? "대상 유실 · " : ""}
                {item.status === "resolved" ? "해결됨" : "열린 댓글"}
            </p>
            <Thread label={`${label}: ${item.id}`}
                comments={item.comments as readonly ThreadComment[]}
                disabled={disabled}
                onReply={onReply ? (parentId, content) =>
                    onReply(item.id, parentId, content) : undefined} />
            <div className="flex flex-wrap gap-2">
                <Button className="h-8 px-2 text-xs" disabled={disabled}
                    onClick={() => onCommentsChange(comments.map((entry) =>
                        entry.id === item.id ? {
                            ...entry,
                            status: entry.status === "open"
                                ? "resolved" : "open",
                        } : entry))}>
                    {item.status === "open" ? "해결" : "다시 열기"}
                </Button>
                {item.anchor === "orphaned" && onReattach &&
                    <Button className="h-8 px-2 text-xs" disabled={disabled}
                        onMouseDown={(event) => event.preventDefault()}
                        onClick={() => onReattach(item.id)}>
                        선택 영역에 다시 연결
                    </Button>}
            </div>
        </section>)}
    </aside>;
}

export { InlineCommentLayer };
export type { InlineCommentLayerProps, InlineComment };
